// Minis straddling every view edge: every mini frame (death set, after the acid frames and
// after the slinky frames) in its type's palette; the tile buffer ends after the death set
static void test_mini_edges(void) {
  using namespace marble_video;
  static const uint8_t RACE = 4;
  const marble_level::Level l = guardedLevel(store.load(RACE), MARBLE_DEATH_TILES);
  const uint8_t ranges[2][2] = {
      {(uint8_t)(marble_physics::deathFrame(ACID_LAST_HDR) + 1),
       marble_physics::deathFrame(SLINKY_FIRST_HDR)},
      {(uint8_t)(marble_physics::deathFrame(SLINKY_LAST_HDR) + 1),
       marble_physics::deathFrame(BIRD_FIRST_HDR)}};
  uint32_t crc = 0;
  for (const auto &r : ranges) {
    for (uint8_t f = r[0]; f < r[1]; f++) {
      for (int16_t x : EDGE_X) {
        for (int16_t y : EDGE_Y) {
          VideoState v = {};
          v.level = RACE;
          v.sx = 20;
          v.sy = 40;
          v.n = 1;
          v.marbleAt = 0;
          v.objs[0] = {f, (uint8_t)(SET_DEATH | (SET_MINI + f % 3)), (int16_t)(x + v.sx),
                       (int16_t)(y + v.sy), 0, 0};
          crc = crc32((const uint8_t *)&crc, sizeof(crc), checkRef(l, v));
        }
      }
    }
  }
  printf("mini edges crc %08x\n", (unsigned)crc);
  TEST_ASSERT_EQUAL_HEX32(MINI_EDGES_CRC, crc);
}

// one object of `frame` (race `race`, palette set `set`) over a playfield whose pixel in column
// x is kPf[x & 7]; every sprite tile byte is `fill` (two pens). base: without the object.
static const uint8_t kPf[8] = {4, 20, 15, 31, 7, 0, 5, 9};

static void objectFrames(uint8_t race, uint8_t frame, uint8_t set, uint8_t lift, uint8_t fill,
                         uint16_t *base, uint16_t *got) {
  static uint8_t px[1][64];
  for (int i = 0; i < 64; i++) px[0][i] = kPf[i & 7];
  static uint16_t pal[128];
  for (int i = 0; i < 128; i++) pal[i] = 0x1000 + i;
  static uint16_t map[marble_level::COLS * 36];
  static uint8_t spr[MARBLE_SPRITE_MAX_TILES][32];
  memset(spr, fill, sizeof(spr));
  const marble_level::Level l = {36, 1, map, px, pal, spr};
  marble_video::VideoState v = {};
  v.level = race;
  v.lift = lift;
  v.n = 1;
  v.marbleAt = 1;
  v.objs[0] = {frame, set, 100, 100};
  marble_video::VideoState none = v;
  none.n = 0;
  for (int row = 0; row < marble_video::OUT_H / 8; row++) {
    marble_video::renderRow(l, none, row, base + row * marble_video::OUT_W * 8);
    marble_video::renderRow(l, v, row, got + row * marble_video::OUT_W * 8);
  }
}

static uint16_t sprBase[marble_video::OUT_W * marble_video::OUT_H];
static uint16_t sprGot[marble_video::OUT_W * marble_video::OUT_H];
static uint16_t sprPlain[marble_video::OUT_W * marble_video::OUT_H];

// wave strip: colour 0x300 + ((playfield pixel & 15) << 4) + pen over playfield pixels 4, 20,
// 15, 31 (and 7, 0, 5, 9). Lit: pf 4 with pen 3 (shade 0), pf 15 with pen 2 (shade 1) and
// pen 3 (shade 2); every other drawn pixel is black, pen 1 shows the playfield.
static void test_shade_colour(void) {
  const MarbleSpriteSet &set = marble_sprites[marble_sprite_race[2]];
  uint8_t frame = 0xff;
  for (uint8_t f = set.nhdr; f < set.nframes && frame == 0xff; f++) {
    if (set.frames[f].ncols) frame = f;
  }
  TEST_ASSERT_NOT_EQUAL(0xff, frame);
  int lit[3] = {};
  for (uint8_t pen = 1; pen <= 3; pen++) {
    objectFrames(2, frame, 8, 0xff, (uint8_t)(pen << 4 | pen), sprBase, sprGot);
    int drawn[8] = {};
    for (int i = 0; i < marble_video::OUT_W * marble_video::OUT_H; i++) {
      if (sprGot[i] == sprBase[i]) continue;
      const int k = kPf[(i % marble_video::OUT_W) & 7] & 15;
      drawn[(i % marble_video::OUT_W) & 7]++;
      int shade = -1;
      if (k == 4 && pen == 3) shade = 0;
      else if (k == 15 && pen == 2) shade = 1;
      else if (k == 15 && pen == 3) shade = 2;
      TEST_ASSERT_EQUAL_HEX16(shade < 0 ? 0 : marble_test_shade[2][shade], sprGot[i]);
      if (shade >= 0) lit[shade]++;
    }
    for (int c = 0; c < 8; c++) {  // pen 1 shows the playfield, pens 2 and 3 reach every kind
      if (pen == 1) TEST_ASSERT_EQUAL_INT(0, drawn[c]);
      else TEST_ASSERT_TRUE(drawn[c] > 0);
    }
  }
  for (int k = 0; k < 3; k++) TEST_ASSERT_TRUE(lit[k] > 0);
}

// tag 3 lift: set 6 pens 1-4 come from marble_lift_pal[lift] for the variants 1-3 (variant 0
// is the default palette), pen 0 stays transparent; lift 4 and up: no substitution
static void test_lift_palette(void) {
  const uint16_t *pal6 = marble_sprite_pal[1][2];
  for (uint8_t lift = 1; lift < 6; lift++) {
    int drawn = 0, replaced = 0;
    for (uint8_t fill = 0x12; fill <= 0x34; fill += 0x22) {  // pens 1 2, then 3 4
      objectFrames(1, 0, 6, 0xff, fill, sprBase, sprPlain);
      objectFrames(1, 0, 6, lift, fill, sprBase, sprGot);
      for (int i = 0; i < marble_video::OUT_W * marble_video::OUT_H; i++) {
        if (sprPlain[i] == sprBase[i]) {
          TEST_ASSERT_EQUAL_HEX16(sprBase[i], sprGot[i]);
          continue;
        }
        drawn++;
        if (lift >= 4) {
          TEST_ASSERT_EQUAL_HEX16(sprPlain[i], sprGot[i]);
          continue;
        }
        int pen = 1;
        while (pen <= 4 && sprPlain[i] != pal6[pen]) pen++;
        TEST_ASSERT_TRUE(pen <= 4);
        TEST_ASSERT_EQUAL_HEX16(marble_lift_pal[lift][pen - 1], sprGot[i]);
        if (sprGot[i] != sprPlain[i]) replaced++;
      }
    }
    TEST_ASSERT_TRUE(drawn > 0);
    if (lift < 4) TEST_ASSERT_TRUE(replaced > 0);
  }
}

static void test_patch(void) {
  const uint16_t *map = store.load(0).map;
  const uint16_t at = 5 * marble_level::COLS + 16;  // block row 2, column 2
  TEST_ASSERT_NOT_EQUAL(0x02f8, map[at]);
  const uint8_t idx = marble_level::patchIndex(0x16660);
  TEST_ASSERT_NOT_EQUAL(marble_level::NO_PATCH, idx);
  TEST_ASSERT_EQUAL_UINT8(marble_level::NO_PATCH, marble_level::patchIndex(0x12345));
  store.patch(idx);
  TEST_ASSERT_EQUAL_HEX16(0x02f8, map[at]);
  store.patch(marble_level::NO_PATCH);  // none: ignored
  TEST_ASSERT_EQUAL_HEX16(0x02f8, map[at]);
  const uint16_t *map1 = store.load(1).map;  // other race: map unchanged
  const uint16_t before = map1[at];
  store.patch(idx);
  TEST_ASSERT_EQUAL_HEX16(before, map1[at]);
}
